import Foundation

/// Writes the Markdown files that let an LLM (or a person) understand the library without opening
/// every file: a root `INDEX.md`, one `COURSE.md` per course, and agent instruction files
/// (`AGENTS.md`, `CLAUDE.md`, `GEMINI.md`) that coding/CLI agents pick up automatically.
///
/// Generated files start with a marker line. A file whose marker was removed is treated as
/// user-owned and never overwritten. Files are only rewritten when their content changes.
public enum LibraryIndexGenerator {
    public static let marker = "<!-- Generated by WhisperLectures. Edits will be overwritten; delete this line to keep your own version. -->"
    public static let indexFileName = "INDEX.md"
    public static let agentFileNames = ["AGENTS.md", "CLAUDE.md", "GEMINI.md"]

    public static func regenerate(rootURL: URL, courses: [Course]) {
        write(indexMarkdown(courses: courses), to: rootURL.appendingPathComponent(indexFileName))
        let guide = agentGuideMarkdown()
        for name in agentFileNames {
            write(guide, to: rootURL.appendingPathComponent(name))
        }
        for course in courses {
            write(courseMarkdown(course), to: course.folderURL.appendingPathComponent(Course.overviewFileName))
        }
    }

    // MARK: - INDEX.md

    public static func indexMarkdown(courses: [Course]) -> String {
        var lines = [marker, "", "# Study Library Index", ""]
        lines.append("Each course is a folder. Open its `COURSE.md` for the lecture list, transcripts and materials. See `AGENTS.md` for how the library is organised.")
        lines.append("")

        lines.append("## Courses")
        lines.append("")
        if courses.isEmpty {
            lines.append("_No courses yet._")
        } else {
            lines.append("| Course | Code | Tags | Lectures | Recordings | Latest lecture | Overview |")
            lines.append("|---|---|---|---|---|---|---|")
            for course in courses {
                let latest = course.lectures.map(\.date).max().map { DateFormats.isoDay.string(from: $0) } ?? "—"
                let recordings = course.lectures.reduce(0) { $0 + course.recordingGroups(for: $1).count }
                // Courses stored outside the library can't be linked relatively.
                let folder = course.isExternal ? course.folderURL.path : course.folderURL.lastPathComponent
                lines.append("| \(cell(course.name)) | \(cell(course.metadata.code)) | \(cell(course.tags.joined(separator: ", "))) | \(course.lectures.count) | \(recordings) | \(latest) | \(link(folder + "/" + Course.overviewFileName, to: folder + "/" + Course.overviewFileName)) |")
            }
        }
        lines.append("")

        var byTag: [String: [String]] = [:]
        for course in courses {
            for tag in course.tags {
                byTag[tag, default: []].append(course.name)
            }
        }
        if !byTag.isEmpty {
            lines.append("## Courses by Tag")
            lines.append("")
            for tag in byTag.keys.sorted(by: { $0.localizedStandardCompare($1) == .orderedAscending }) {
                lines.append("- **\(tag)**: \(byTag[tag]!.joined(separator: ", "))")
            }
            lines.append("")
        }
        return lines.joined(separator: "\n")
    }

    // MARK: - COURSE.md

    public static func courseMarkdown(_ course: Course) -> String {
        var lines = [marker, ""]
        lines.append("# \(course.displayName)")
        lines.append("")
        if !course.metadata.code.isEmpty {
            lines.append("- **Code**: \(course.metadata.code)")
        }
        if !course.tags.isEmpty {
            lines.append("- **Tags**: \(course.tags.joined(separator: ", "))")
        }
        lines.append("- **Lectures**: \(course.lectures.count)")
        lines.append("- **Materials**: \(course.materials.count) file\(course.materials.count == 1 ? "" : "s") in `\(Course.materialsFolderName)/`")
        lines.append("")

        lines.append("## Lectures")
        lines.append("")
        if course.lectures.isEmpty {
            lines.append("_No lectures yet._")
        } else {
            lines.append("| Lecture | Title | Date | Transcripts |")
            lines.append("|---|---|---|---|")
            for lecture in course.lectures {
                let groups = course.recordingGroups(for: lecture)
                let transcriptLinks = groups.compactMap { group -> String? in
                    guard let file = group.primaryFile else { return nil }
                    return link(group.baseName, to: "\(Course.transcriptsFolderName)/\(file.name)")
                }
                let transcripts = transcriptLinks.isEmpty ? "—" : transcriptLinks.joined(separator: "<br>")
                lines.append("| \(lecture.label) | \(cell(lecture.title)) | \(DateFormats.isoMinute.string(from: lecture.date)) | \(transcripts) |")
            }
        }
        lines.append("")

        lines.append("## Materials")
        lines.append("")
        if course.materials.isEmpty {
            lines.append("_No materials yet._")
        } else {
            for file in course.materials {
                lines.append("- \(link(file.name, to: "\(Course.materialsFolderName)/\(file.name)"))")
            }
        }
        lines.append("")

        if !course.notes.isEmpty {
            lines.append("## Notes")
            lines.append("")
            lines.append("Written by the student in Markdown. `[[Name]]` links point to other notes, lectures or files.")
            lines.append("")
            for note in course.notes {
                lines.append("- \(link(note.name, to: "\(Course.notesFolderName)/\(note.url.lastPathComponent)"))")
            }
            lines.append("")
        }

        let unassigned = course.unassignedRecordingGroups
        if !unassigned.isEmpty {
            lines.append("## Other Transcripts")
            lines.append("")
            lines.append("Not linked to a specific lecture.")
            lines.append("")
            for group in unassigned {
                if let file = group.primaryFile {
                    lines.append("- \(link(file.name, to: "\(Course.transcriptsFolderName)/\(file.name)"))")
                }
            }
            lines.append("")
        }
        return lines.joined(separator: "\n")
    }

    // MARK: - AGENTS.md / CLAUDE.md / GEMINI.md

    public static func agentGuideMarkdown() -> String {
        """
        \(marker)

        # Study Library: Guide for AI Assistants

        This folder is a student's study library created by WhisperLectures. It holds lecture transcripts and course materials. Use it to answer questions about the courses, explain concepts, make summaries and revision notes, and quiz the student.

        ## Layout

        ```
        INDEX.md                       All courses with tags, lecture counts and links. Start here.
        <Course folder>/
          COURSE.md                    Lecture table (number, title, date, transcripts) and materials list.
          course.json                  The same data in machine-readable form.
          materials/                   Slides, PDFs, readings and notes for the whole course.
          notes/                       The student's own Markdown notes (LaTeX math, [[wikilinks]]).
          transcripts/
            <Course>_L03_R1.md         Transcript of lecture 3, recording 1 (preferred for reading).
            <Course>_L03_R1.txt        Same transcript, plain text (optional).
            <Course>_L03_R1.srt/.vtt   Same transcript as subtitles (optional; skip these).
          .whisperlectures/            App data. Ignore.
        ```

        - Lecture numbers are zero-padded: `L03` is lecture 3. A lecture can have several recordings (`R1`, `R2`, ...), for example when a recording was split in two. Read all recordings of a lecture in order.
        - Each Markdown transcript begins with a YAML header: `course`, `course_code`, `lecture`, `lecture_title`, `lecture_date`, `recording`, `source_audio`, `model`, `transcribed_at`, `duration`.
        - Paragraphs in transcripts start with a `[mm:ss]` timestamp (`[h:mm:ss]` past one hour) measured from the start of that recording.
        - `course.json` and `COURSE.md` are always current. If a lecture is renamed or re-dated later, older transcript headers may still show the old values, so trust `COURSE.md`.
        - Dates use the format `YYYY-MM-DD HH:MM`, in local time.

        ## How to Answer

        1. To find content, read `INDEX.md`, then the relevant `COURSE.md`, then only the transcripts and materials you need. For broad questions, search across `transcripts/` (for example with grep) before reading whole files.
        2. Cite sources as `<course> L<n> [mm:ss]` for transcripts, or as the file name and page or slide number for materials.
        3. Transcripts are automatic speech recognition and may mishear names, technical terms, formulas and numbers. Where possible, check them against `materials/`, and say so when something is uncertain.
        4. Prefer what the lecturer actually said and what the course materials say over general knowledge. Label anything you add from outside the course.
        5. Don't edit, rename or delete files unless the student asks. `INDEX.md`, `COURSE.md` and this file are regenerated by the app.
        6. If the student asks you to save output, such as summaries or flashcards, write a new Markdown file in that course's `materials/` folder with a clear name, for example `L03 summary.md`.

        ## Useful Requests

        - "Summarise lecture 3 of <course> with timestamps for each topic."
        - "Make revision notes for <course> from lectures 1 to 6, grouped by topic."
        - "What did the lecturer say about <topic>? Quote the transcript and cite it."
        - "Write 10 exam-style questions from <course>, with answers and sources."
        - "Which of my courses tagged <tag> cover <topic>?"

        """
    }

    // MARK: - Helpers

    static func write(_ content: String, to url: URL) {
        if let existing = try? String(contentsOf: url, encoding: .utf8) {
            guard existing.hasPrefix(marker) else { return }  // user took ownership of this file
            guard existing != content else { return }
        }
        try? content.write(to: url, atomically: true, encoding: .utf8)
    }

    static func cell(_ text: String) -> String {
        text.replacingOccurrences(of: "|", with: "\\|").replacingOccurrences(of: "\n", with: " ")
    }

    /// Markdown link with an angle-bracket destination so spaces in paths work.
    static func link(_ title: String, to path: String) -> String {
        "[\(cell(title))](<\(path)>)"
    }
}
